INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1675441, 226930, 41845, '<td valign="top">I like the dual contrast in this image from dark to light and blue to yellow - I don''t know how high it will score but I like the almost pencil sketch affect you''ve achieved in this image. some people may comment that it''s poorly focused or you should have used a faster iso but sometimes are subjects are not so easily controlled as to let us get all the settings adjusted just right :).</td>', 'I like the dual contrast in this image from dark to light and blue to yellow - I don''t know how high it will score but I like the almost pencil sketch affect you''ve achieved in this image. some people may comment that it''s poorly focused or you should have used a faster iso but sometimes are subjects are not so easily controlled as to let us get all the settings adjusted just right :).', '2005-09-05 10:48:41.000000', NULL, 1),
(1675444, 226758, 27763, '<td valign="top">Wow, that light/dark pattern on the right wall is really interesting.  And the 50 Street sign adds balance and interest to the composition.</td>', 'Wow, that light/dark pattern on the right wall is really interesting.  And the 50 Street sign adds balance and interest to the composition.', '2005-09-05 10:49:08.000000', NULL, 1),
