(1685531, 226939, 27164, '<td valign="top">Wonderful subject matter and composition!  One of the best color high-contrasts I''ve seen in the challenge yet.  A truly beautiful shot.  The thing that really makes this photo for me even more is the sillhouette of the bridge in back, it adds even MORE contrast to the already contrasty complimentary colors of orange and blue.  I really like what you''ve done here, going in my favorites.  :)</td>', 'Wonderful subject matter and composition!  One of the best color high-contrasts I''ve seen in the challenge yet.  A truly beautiful shot.  The thing that really makes this photo for me even more is the sillhouette of the bridge in back, it adds even MORE contrast to the already contrasty complimentary colors of orange and blue.  I really like what you''ve done here, going in my favorites.  :)', '2005-09-08 01:20:18.000000', NULL, 1),
(1685533, 227005, 12750, '<td valign="top">Excellent.  If the noise could be cleaned up in the shadow/lower part of the image. Seems like a high ISO was used?</td>', 'Excellent.  If the noise could be cleaned up in the shadow/lower part of the image. Seems like a high ISO was used?', '2005-09-08 01:20:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1685540, 226994, 12750, '<td valign="top">without the title, very hard to make out what this even is.  With the title its still hard to see.</td>', 'without the title, very hard to make out what this even is.  With the title its still hard to see.', '2005-09-08 01:21:37.000000', NULL, 1),
(1685551, 226946, 41802, '<td valign="top">Nice suprise photo to have in the contest!</td>', 'Nice suprise photo to have in the contest!', '2005-09-08 01:24:00.000000', NULL, 1),
(1685553, 224248, 41802, '<td valign="top">Wow awesome shot!!!</td>', 'Wow awesome shot!!!', '2005-09-08 01:24:30.000000', NULL, 1),
(1685555, 226825, 41802, '<td valign="top">Love the colors, so bright!</td>', 'Love the colors, so bright!', '2005-09-08 01:24:43.000000', NULL, 1),
(1685559, 227094, 41802, '<td valign="top">Wow the contrast is deep, almost a little creepy with the eyes.</td>', 'Wow the contrast is deep, almost a little creepy with the eyes.', '2005-09-08 01:25:38.000000', NULL, 1),
(1685568, 226535, 27789, '<td valign="top">I enjoy the shot composition, the colors, but it feels a little overprocessed.</td>', 'I enjoy the shot composition, the colors, but it feels a little overprocessed.', '2005-09-08 01:26:54.000000', NULL, 1),
(1685573, 226401, 41802, '<td valign="top">Yea out of the box thinking! Great shot!</td>', 'Yea out of the box thinking! Great shot!', '2005-09-08 01:29:07.000000', NULL, 1),
(1685591, 227056, 41802, '<td valign="top">Wow the eyes in this challenge have been amazing, but these are the best I have seen so far.</td>', 'Wow the eyes in this challenge have been amazing, but these are the best I have seen so far.', '2005-09-08 01:39:58.000000', NULL, 1),
(1685599, 227016, 41802, '<td valign="top">Wow awesome!! The yellow really brings them out.</td>', 'Wow awesome!! The yellow really brings them out.', '2005-09-08 01:45:34.000000', NULL, 1),
(1685614, 226559, 41802, '<td valign="top">Lovely shot! The dress is amazing.</td>', 'Lovely shot! The dress is amazing.', '2005-09-08 01:50:52.000000', NULL, 1),
(1685620, 225738, 41802, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2005-09-08 01:56:08.000000', NULL, 1),
(1685623, 226669, 41802, '<td valign="top">Wow is that a catapillar? Great shot!</td>', 'Wow is that a catapillar? Great shot!', '2005-09-08 02:01:05.000000', NULL, 1),
(1685670, 224971, 36619, '<td valign="top">stunning portrait.</td>', 'stunning portrait.', '2005-09-08 02:36:12.000000', NULL, 1),
(1685685, 225248, 40718, '<td valign="top">Great picture, but my histogram says not high contrast at all. Best I can give you is a 5.</td>', 'Great picture, but my histogram says not high contrast at all. Best I can give you is a 5.', '2005-09-08 02:46:25.000000', NULL, 1),
(1685686, 226781, 40718, '<td valign="top">Nice.  Kittens always make good subjects. 7</td>', 'Nice.  Kittens always make good subjects. 7', '2005-09-08 02:47:01.000000', NULL, 1),
(1685690, 224911, 40718, '<td valign="top">I feel like this shot was in a previous challenge...6</td>', 'I feel like this shot was in a previous challenge...6', '2005-09-08 02:49:08.000000', NULL, 1),
(1685789, 225928, 30214, '<td valign="top">nice colors, but I can''t quite get the composition. What is this black square in the top left which is blocking the rest of the landscape?</td>', 'nice colors, but I can''t quite get the composition. What is this black square in the top left which is blocking the rest of the landscape?', '2005-09-08 04:38:45.000000', NULL, 1),
(1685791, 227109, 30214, '<td valign="top">great contrast indeed. excellent job</td>', 'great contrast indeed. excellent job', '2005-09-08 04:39:14.000000', NULL, 1),
(1685793, 226885, 30214, '<td valign="top">the centered composition is a bit boring. and except for a blown-out sun reflection, it is not a high contrast photo, in my opinion.</td>', 'the centered composition is a bit boring. and except for a blown-out sun reflection, it is not a high contrast photo, in my opinion.', '2005-09-08 04:40:28.000000', NULL, 1),
(1685794, 226899, 30214, '<td valign="top">nice contrast, but too much noise in the sky distracts a bit.</td>', 'nice contrast, but too much noise in the sky distracts a bit.', '2005-09-08 04:41:31.000000', NULL, 1),
(1685795, 227092, 30214, '<td valign="top">this contrast feels very artificial...</td>', 'this contrast feels very artificial...', '2005-09-08 04:42:20.000000', NULL, 1),
(1685796, 224347, 30214, '<td valign="top">nice shot. very on-topic</td>', 'nice shot. very on-topic', '2005-09-08 04:42:54.000000', NULL, 1),
(1685798, 227019, 30214, '<td valign="top">i like the colors a lot, but why not straighten the building in p/p?</td>', 'i like the colors a lot, but why not straighten the building in p/p?', '2005-09-08 04:44:30.000000', NULL, 1),
(1685799, 227061, 30214, '<td valign="top">great composition, and colors are reasonably contrasty</td>', 'great composition, and colors are reasonably contrasty', '2005-09-08 04:44:59.000000', NULL, 1),
(1685801, 226946, 30214, '<td valign="top">I like it a lot! would be great for the color portrait challenge, too  :) <br/></td>', 'I like it a lot! would be great for the color portrait challenge, too  :) ', '2005-09-08 04:46:16.000000', NULL, 1),
(1685804, 225864, 30214, '<td valign="top">i don''t think that a blown-out background amounts to a high-contrast shot... Nice portrait, though.</td>', 'i don''t think that a blown-out background amounts to a high-contrast shot... Nice portrait, though.', '2005-09-08 04:47:18.000000', NULL, 1),
(1685805, 226930, 30214, '<td valign="top">great job!</td>', 'great job!', '2005-09-08 04:47:46.000000', NULL, 1),
(1685806, 226504, 30214, '<td valign="top">nice shot</td>', 'nice shot', '2005-09-08 04:48:28.000000', NULL, 1),
(1685810, 226791, 30214, '<td valign="top">excellent portrait. And high-contrast, too, as far as I understand.</td>', 'excellent portrait. And high-contrast, too, as far as I understand.', '2005-09-08 04:49:20.000000', NULL, 1),
(1685812, 226807, 30214, '<td valign="top">This IS high-contrast! Fantastic portrait! (would work great for the color portrait challenge, too :))</td>', 'This IS high-contrast! Fantastic portrait! (would work great for the color portrait challenge, too :))', '2005-09-08 04:50:33.000000', NULL, 1),
(1685815, 227075, 30214, '<td valign="top">nice technique.</td>', 'nice technique.', '2005-09-08 04:51:05.000000', NULL, 1),
(1685818, 226806, 30214, '<td valign="top">i think it is actually low contrast. And not particularly sharp, too...</td>', 'i think it is actually low contrast. And not particularly sharp, too...', '2005-09-08 04:52:33.000000', NULL, 1),
(1685819, 226915, 30214, '<td valign="top">great portrait! and high contrast, too...</td>', 'great portrait! and high contrast, too...', '2005-09-08 04:52:55.000000', NULL, 1),
(1685824, 225674, 30214, '<td valign="top">it''s a great concept, but IMO  this kind of photo really need perfect sharpness in all elements. As it is, it is only focused on lashes, the DOF should''ve been increased a bit.</td>', 'it''s a great concept, but IMO  this kind of photo really need perfect sharpness in all elements. As it is, it is only focused on lashes, the DOF should''ve been increased a bit.', '2005-09-08 04:54:48.000000', NULL, 1),
(1685826, 225623, 30214, '<td valign="top">it would work better for the "perspective" challenge, IMO. Nice shot, regardless.</td>', 'it would work better for the "perspective" challenge, IMO. Nice shot, regardless.', '2005-09-08 04:55:41.000000', NULL, 1),
(1685828, 225903, 30214, '<td valign="top">nice contrasty colors</td>', 'nice contrasty colors', '2005-09-08 04:55:59.000000', NULL, 1),
(1685905, 226748, 23430, '<td valign="top">Not too exciting but it is original and high contrast</td>', 'Not too exciting but it is original and high contrast', '2005-09-08 06:16:03.000000', NULL, 1),
(1686016, 226586, 19831, '<td valign="top">A good idea here. Seems like the presentation could be improved by a little bit sharper focus and some levels tweaking maybe.</td>', 'A good idea here. Seems like the presentation could be improved by a little bit sharper focus and some levels tweaking maybe.', '2005-09-08 07:22:40.000000', NULL, 1),
(1686018, 225702, 19831, '<td valign="top">Nice idea and a cool perspective here. Lighting seems to be a little dull. Perhaps even a little tweaking of levels could enhance the presentation.</td>', 'Nice idea and a cool perspective here. Lighting seems to be a little dull. Perhaps even a little tweaking of levels could enhance the presentation.', '2005-09-08 07:24:44.000000', NULL, 1),
(1686019, 226796, 19831, '<td valign="top">Beautiful shot. Nice choice of subject. I like your treatment of it, and the centered composition seems to really work well in this case. Good job.</td>', 'Beautiful shot. Nice choice of subject. I like your treatment of it, and the centered composition seems to really work well in this case. Good job.', '2005-09-08 07:26:01.000000', NULL, 1),
(1686022, 225955, 19831, '<td valign="top">Cool idea. I like how the white really stands out. I think that this shot could maybe benefit from a tighter cropping. Especially at the top, the frame or bar, or whatever that line is across the top seems to really take a lot away from the image.</td>', 'Cool idea. I like how the white really stands out. I think that this shot could maybe benefit from a tighter cropping. Especially at the top, the frame or bar, or whatever that line is across the top seems to really take a lot away from the image.', '2005-09-08 07:29:17.000000', NULL, 1),
(1686029, 224971, 37334, '<td valign="top">Really nice use of the dress neckline to create the white triangle.</td>', 'Really nice use of the dress neckline to create the white triangle.', '2005-09-08 07:34:18.000000', NULL, 1),
(1686030, 227058, 19831, '<td valign="top">Excellant intrepretation on the challenge. High contrast on many levels. Really nice job. good dof and nice composition also.</td>', 'Excellant intrepretation on the challenge. High contrast on many levels. Really nice job. good dof and nice composition also.', '2005-09-08 07:34:31.000000', NULL, 1),
(1686031, 226778, 19831, '<td valign="top">Great shot. Nice composition, very interesting. Good contrast. Nice job.</td>', 'Great shot. Nice composition, very interesting. Good contrast. Nice job.', '2005-09-08 07:35:51.000000', NULL, 1),
(1686032, 227017, 19831, '<td valign="top">Beautiful photo. I like your treatment here. Good use of dof. Nice job.</td>', 'Beautiful photo. I like your treatment here. Good use of dof. Nice job.', '2005-09-08 07:37:17.000000', NULL, 1),
(1686033, 224793, 19831, '<td valign="top">Great photo. Nice contrast. Good interest factor. I like the perspective. Nice job.</td>', 'Great photo. Nice contrast. Good interest factor. I like the perspective. Nice job.', '2005-09-08 07:38:37.000000', NULL, 1),
(1686038, 225940, 19831, '<td valign="top">Beautiful idea. I love this perspective. I also really like your treatment of the photo. I''m thinking that if the light showed a little bit more of the ear, it could make this fine shot even better. Nice job.</td>', 'Beautiful idea. I love this perspective. I also really like your treatment of the photo. I''m thinking that if the light showed a little bit more of the ear, it could make this fine shot even better. Nice job.', '2005-09-08 07:46:56.000000', NULL, 1),
(1686046, 225298, 19831, '<td valign="top">Nice choice of subject. This particular pov seems a little too busy, and the photo feels a little bit too sharp.</td>', 'Nice choice of subject. This particular pov seems a little too busy, and the photo feels a little bit too sharp.', '2005-09-08 07:55:01.000000', NULL, 1),
