(1687376, 225799, 40977, '<td valign="top">Great Job....I love the effects and the imagery is wonderfull.  - 8 -</td>', 'Great Job....I love the effects and the imagery is wonderfull.  - 8 -', '2005-09-08 17:11:51.000000', NULL, 1),
(1687379, 227028, 27845, '<td valign="top">It''s a pity that there''s so little to recognize in the face. I''d have preferred it completely dark rather than this. That apart, This is a cool image. The saxophon leads the eye smoothly up to the face, the neck makes a curve and the arms lead my attention back down again. Excellent composition. 9.</td>', 'It''s a pity that there''s so little to recognize in the face. I''d have preferred it completely dark rather than this. That apart, This is a cool image. The saxophon leads the eye smoothly up to the face, the neck makes a curve and the arms lead my attention back down again. Excellent composition. 9.', '2005-09-08 17:12:07.000000', NULL, 1),
(1687380, 226802, 40977, '<td valign="top">Great Job.  Terrific shadowing -- 7 --</td>', 'Great Job.  Terrific shadowing -- 7 --', '2005-09-08 17:12:09.000000', NULL, 1),
(1687381, 227049, 10985, '<td valign="top">This is original in subject and set-up, and also in the choice of such a pale subject for high contrast on white. But it does work pretty well!</td>', 'This is original in subject and set-up, and also in the choice of such a pale subject for high contrast on white. But it does work pretty well!', '2005-09-08 17:12:14.000000', NULL, 1),
(1687382, 226574, 40977, '<td valign="top">Clever.  Nice Job</td>', 'Clever.  Nice Job', '2005-09-08 17:12:22.000000', NULL, 1),
(1687383, 226728, 10985, '<td valign="top">Very contrasty and effective!</td>', 'Very contrasty and effective!', '2005-09-08 17:12:42.000000', NULL, 1),
(1687384, 226663, 40977, '<td valign="top">Love the color in the sky and the overall effect of the image.  - 7 -</td>', 'Love the color in the sky and the overall effect of the image.  - 7 -', '2005-09-08 17:12:42.000000', NULL, 1),
(1687386, 224484, 40977, '<td valign="top">Very cool!!!  Great Colors and great shot -- 7 --</td>', 'Very cool!!!  Great Colors and great shot -- 7 --', '2005-09-08 17:13:08.000000', NULL, 1),
(1687387, 227030, 10985, '<td valign="top">Classic high contrast. Well done!</td>', 'Classic high contrast. Well done!', '2005-09-08 17:13:14.000000', NULL, 1),
(1687389, 227005, 40977, '<td valign="top">Wow!!!  Great Job.  Love the colors and the shadow....the textures  Geez could go on and on with all the wonderfull images this shot has and normally that makes it too busy a shot for me, but you really did an excellent job.  - 8 -</td>', 'Wow!!!  Great Job.  Love the colors and the shadow....the textures  Geez could go on and on with all the wonderfull images this shot has and normally that makes it too busy a shot for me, but you really did an excellent job.  - 8 -', '2005-09-08 17:14:18.000000', NULL, 1),
(1687390, 225006, 40977, '<td valign="top">Very cool idea.  Great Job</td>', 'Very cool idea.  Great Job', '2005-09-08 17:14:35.000000', NULL, 1),
(1687391, 227056, 27845, '<td valign="top">The blown-out highlights in the eye remind me of grigrigirl''s style. I think the dodging is a bit excessive just over the eyes, but that might be make-up as well :) 9.</td>', 'The blown-out highlights in the eye remind me of grigrigirl''s style. I think the dodging is a bit excessive just over the eyes, but that might be make-up as well :) 9.', '2005-09-08 17:14:40.000000', NULL, 1),
(1687394, 225108, 40977, '<td valign="top">What is it???  Regardless a great shot....looks like some futuristic bowling alley (lol)  -- 7 --</td>', 'What is it???  Regardless a great shot....looks like some futuristic bowling alley (lol)  -- 7 --', '2005-09-08 17:15:27.000000', NULL, 1),
(1687396, 227084, 17033, '<td valign="top">Bizarre fairytale light! Very interesting combination of colour and form</td>', 'Bizarre fairytale light! Very interesting combination of colour and form', '2005-09-08 17:15:48.000000', NULL, 1),
(1687397, 226854, 40977, '<td valign="top">What can I say....colors don''t come any sharper than this.  Great shot</td>', 'What can I say....colors don''t come any sharper than this.  Great shot', '2005-09-08 17:15:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1687401, 226728, 40977, '<td valign="top">You pulled off what could have been a very distracting and busy shot. Well done.</td>', 'You pulled off what could have been a very distracting and busy shot. Well done.', '2005-09-08 17:16:16.000000', NULL, 1),
(1687402, 226358, 40977, '<td valign="top">Great close up.</td>', 'Great close up.', '2005-09-08 17:16:42.000000', NULL, 1),
(1687405, 227028, 4477, '<td valign="top">Nice subject and composition!</td>', 'Nice subject and composition!', '2005-09-08 17:17:10.000000', NULL, 1),
(1687406, 226547, 10985, '<td valign="top">Great-looking camera! And very good contrast job.</td>', 'Great-looking camera! And very good contrast job.', '2005-09-08 17:17:39.000000', NULL, 1),
(1687407, 226991, 4477, '<td valign="top">Nice job in making something ordinary zing with color!</td>', 'Nice job in making something ordinary zing with color!', '2005-09-08 17:17:44.000000', NULL, 1),
(1687408, 227095, 40977, '<td valign="top">Alright....is it a miniture??  This one has me stumped. Regardless a really creative and interesting shot.  Great job.</td>', 'Alright....is it a miniture??  This one has me stumped. Regardless a really creative and interesting shot.  Great job.', '2005-09-08 17:17:46.000000', NULL, 1),
