(1687414, 227073, 17033, '<td valign="top">Crop off top third  (to just under lamps) and this would be simply stunning...now, it is just very, very good!</td>', 'Crop off top third  (to just under lamps) and this would be simply stunning...now, it is just very, very good!', '2005-09-08 17:18:58.000000', NULL, 1),
(1687415, 226746, 10985, '<td valign="top">Autumn light, already. Nice catch!</td>', 'Autumn light, already. Nice catch!', '2005-09-08 17:19:20.000000', NULL, 1),
