INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1691864, 225407, 24073, '<td valign="top">Im betting this one would of done great in the portrait challenge too.  Owe nevermind that was a color challenge.  Ok, well hey two thumbs up from my way anyway.</td>', 'Im betting this one would of done great in the portrait challenge too.  Owe nevermind that was a color challenge.  Ok, well hey two thumbs up from my way anyway.', '2005-09-10 01:04:13.000000', NULL, 1),
(1691865, 226180, 24613, '<td valign="top">The white sky and the shadows make this a great shot! Good work!</td>', 'The white sky and the shadows make this a great shot! Good work!', '2005-09-10 01:04:22.000000', NULL, 1),
(1691866, 227044, 24613, '<td valign="top">Nice try, but it''s quite out of focus.</td>', 'Nice try, but it''s quite out of focus.', '2005-09-10 01:05:08.000000', NULL, 1),
(1691870, 226134, 24613, '<td valign="top">Sharp car and nice border! ")</td>', 'Sharp car and nice border! ")', '2005-09-10 01:05:44.000000', NULL, 1),
(1691871, 225680, 41802, '<td valign="top">Nice shot, the rock/wood is amazing.</td>', 'Nice shot, the rock/wood is amazing.', '2005-09-10 01:05:48.000000', NULL, 1),
(1691873, 226823, 13688, '<td valign="top">this image has a ton of feeling to it.  i generally like heavy processing, but you have such an astounding image to work with i wish you didn''t go as heavy as you did.  it feels so much like a drawing it loses it''s realness that was it''s strongest suit. well that and a fantastic composition.   anyway you look at it, it''s still great work.  i''m very curious to see how it is received.</td>', 'this image has a ton of feeling to it.  i generally like heavy processing, but you have such an astounding image to work with i wish you didn''t go as heavy as you did.  it feels so much like a drawing it loses it''s realness that was it''s strongest suit. well that and a fantastic composition.   anyway you look at it, it''s still great work.  i''m very curious to see how it is received.', '2005-09-10 01:06:15.000000', NULL, 1),
(1691874, 227028, 41802, '<td valign="top">Nice lighting.  The hand positioning seems a little odd, but good shot.</td>', 'Nice lighting.  The hand positioning seems a little odd, but good shot.', '2005-09-10 01:06:32.000000', NULL, 1),
