(1695662, 226535, 41675, '<td valign="top">While the colors are contrasting, to me, it seems....forced on the train and in the sky.</td>', 'While the colors are contrasting, to me, it seems....forced on the train and in the sky.', '2005-09-11 18:54:55.000000', NULL, 1),
(1695664, 225799, 40718, '<td valign="top">I''m curious as to how the effect was obtained below her dress. 6</td>', 'I''m curious as to how the effect was obtained below her dress. 6', '2005-09-11 18:55:28.000000', NULL, 1),
(1695665, 225752, 41675, '<td valign="top">Some contrast, but much of this photo seems to be similar in grayscale values.</td>', 'Some contrast, but much of this photo seems to be similar in grayscale values.', '2005-09-11 18:55:44.000000', NULL, 1),
(1695666, 226782, 40718, '<td valign="top">I like the idea, but the photo is uninspiring.  5</td>', 'I like the idea, but the photo is uninspiring.  5', '2005-09-11 18:56:00.000000', NULL, 1),
(1695671, 225640, 41675, '<td valign="top">Some contrast on the waves and with the bird, but far too much sky which tends to soften some of the overall contrast...at least for me.</td>', 'Some contrast on the waves and with the bird, but far too much sky which tends to soften some of the overall contrast...at least for me.', '2005-09-11 18:56:33.000000', NULL, 1),
