(1696257, 224876, 33672, '<td valign="top">Fresh Idea that lends to an interesting comp.  Very well executed.</td>', 'Fresh Idea that lends to an interesting comp.  Very well executed.', '2005-09-11 22:45:02.000000', NULL, 1),
(1696259, 226107, 33672, '<td valign="top">Great eyes and lighting. Shadows make an interesting comp.</td>', 'Great eyes and lighting. Shadows make an interesting comp.', '2005-09-11 22:45:50.000000', NULL, 1),
(1696260, 224248, 41675, '<td valign="top">Wow - that''s some closeup. Good contrast on the eye.</td>', 'Wow - that''s some closeup. Good contrast on the eye.', '2005-09-11 22:46:11.000000', NULL, 1),
(1696261, 226807, 1717, '<td valign="top">love the gritty feel here and the background really adds a lot of interest.  amazing detail and tone.  well done! :)</td>', 'love the gritty feel here and the background really adds a lot of interest.  amazing detail and tone.  well done! :)', '2005-09-11 22:46:23.000000', NULL, 1),
